    'alt_work-lash-lift' => ['Laminowanie rzęs i brwi — efekt po zabiegu', 'Ламінування вій і брів — результат', 'Lash lift and brow lamination result'],
    'alt_work-barber-classic' => ['Klasyczne strzyżenie męskie — barber NOX Warszawa', 'Класична чоловіча стрижка — барбер NOX Варшава', 'Classic men’s haircut — NOX barber Warsaw'],
